import flow from 'lodash/fp/flow';
import map from 'lodash/fp/map';
import reduce from 'lodash/fp/reduce';
import flatten from 'lodash/fp/flatten';
import findLastIndex from 'lodash/fp/findLastIndex';

import {
  Suggestion,
  BuildingSuggestion,
  ThinksuggestResponse,
  ThinksuggestAd,
  Engines,
} from '../types';
import { createOrganicSuggestion, getFaviconUrl } from '../selectors/suggestions/utils';

const formatAds = (q: string, engine: Engines, data: ThinksuggestResponse): Suggestion[] => {
  const formatValue = (value) => value.replace(/~/g, q);

  if (!data || !data.suggestions) return null;

  return flow(
    map((key: string): BuildingSuggestion | BuildingSuggestion[] => {
      const value = data.suggestions[key];
      const term = formatValue(key);
      const list = (Array.isArray(value) || !value) ? value : Object.values(value);

      if (!value || !list.length) {
        return createOrganicSuggestion({ term }, engine);
      }

      return [list[0]]
        .map((ad: ThinksuggestAd): BuildingSuggestion => {
          if (!ad.a) return createOrganicSuggestion({ term }, engine);

          const url = (() => {
            const query = new URLSearchParams({
              m: 'c',
              subid: 'ntp',
              pid: process.env.THINKSUGGEST_PID,
              q: q,
              k: term,
              t: ad.t,
              h: formatValue(ad.h),
              ... (ad.s && {s: ad.s}),
            });
            return `https://api.thinksuggest.org?${query}`;
          })();

          return {
            id: url,
            url,
            displayUrl: formatValue(ad.u),

            // brandDomain?: string;
            // impressionUrl?: string;
            term,
            // label?: string;
            // type: 'ad',
            type: 'organic',

            favIconUrl: getFaviconUrl(formatValue(ad.u)),
            // query?: Record<string, string>
            // priority?: number;

            provider: 'thinksuggest',
            // revenue?: number,
          };
        })
    }),
    flatten,

    // only unique urls
    (list: BuildingSuggestion[]) => list
      .filter((s: BuildingSuggestion, index, arr) => {
        if (s.term === q && !s.displayUrl) return false;
        if (!s.displayUrl) return true;

        return findLastIndex(
          (el: BuildingSuggestion) => el.displayUrl === s.displayUrl
        )(arr) === index;
      }),

    reduce((() => {
      let adsCounter = 0;

      return (acc, el) => {
        if (!el.displayUrl) return [...acc, el];

        adsCounter += 1;
        return [
          ...acc,
          adsCounter > 3 ? createOrganicSuggestion({ term: el.term }, engine) : el
        ];
      }
    })(), []),

    // (list) => ([
    //   createOrganicSuggestion({ term: q, type: 'organicProvided' }, engine),
    //   ...list,
    // ]),

  )(Object.keys(data.suggestions)) as Suggestion[];

};

export const fetchThinksuggest = async (q: string, engine: Engines, suggestions: string[]): Promise<Suggestion[]> => {
  const searchParams = new URLSearchParams({
    q,
    m: 's',
    subid: 'ntp',
    pid: process.env.THINKSUGGEST_PID,

    // fc: 'GB',
    // ul: 'EN',
    // uc: 'GB',

    mo: '3',
    ps: suggestions.join('\n'),
  });

  const res = await fetch(`https://api.thinksuggest.org?${searchParams}`);

  if (!res.ok) {
    const text = await res.text();
    console.error(`fetchThinksuggest:${res.status}`, text);
    return null;
  }

  const result: ThinksuggestResponse = await res.json();
  return formatAds(q, engine, result);
}
