const inMemory = {};

export const requestOrganicSuggestions = async (q: string, engine: string, searchTag?: SearchTag): Promise<string[] | BuildingSuggestion[]> => {
  if (!q) return [];

  try {
    // const isWeb = process.env.NODE_ENV === 'production' &&
    //   process.env.APP_PLATFORM === 'web';
    const isWeb = process.env.APP_PLATFORM === 'web';
    const { suggestionsUrl, query, formatter } = isWeb ? ENGINES.oh : ENGINES[engine];

    const url = `${suggestionsUrl}?${new URLSearchParams(query(q, searchTag))}`;
    if (!inMemory[url]) {
      const response = await fetch(url);
      try {
        if (response.ok) {
          inMemory[url] = await formatter(response);
        }
      } catch (err) {
        console.error('formatter', err);
      }
    }

    return inMemory[url] || [];
  } catch (err) {
    console.error('requestOrganicSuggestions', err);
    return [];
  }
};

export const requestAdmarketplaceLongTailSuggestions = async (qt: string): Promise<AdMarketplaceLongTailData> => {
  const defaultResult = {
    status: { code: null, text: null },
    adlistings: { listing: [] },
    count: '0',
    response: null,
  }

  if (!qt) return defaultResult;

  try {
    const ip = localStorage.getItem('ip');
    // '96.41.207.187'
    const qs = new URLSearchParams({
      qt,
      partner: 'oceanhero_extn_search',
      sub1: 'oceanhero',
      v: '7',
      ...(ip && { ip }),
      ua: navigator.userAgent,
      rfr: 'https://chrome.google.com/webstore/detail/oceanhero-save-the-oceans/cdbccfkcpkmimlajcjpodelocoeifjhp',
      results: '2',
      out: 'json',
    });

    const url = `https://${qs.get('partner')}.ampfeed.com/xmlamp/feed?${qs}`;
    if (!inMemory[url]) {
      const response = await fetch(url, { signal: timeoutSignal(2000) });
      inMemory[url] = response.status === 200 ? (await response.json()) : null;
    }

    return inMemory[url];
  } catch (err) {
    console.error('requestAdSuggestions', err);
    return defaultResult;
  }
};

