export const requestAdSuggestions = async (qt: string): Promise<AdMarketplaceData> => {
  const adSuggestionsDefault = {
    original_qt: qt,
    paid_suggestions: [],
    organic_suggestions: [],
  }

  if (!qt) return adSuggestionsDefault;

  try {
    const ip = localStorage.getItem('ip');
    // '96.41.207.187'
    const qs = new URLSearchParams({
      qt,
      partner: 'oceanhero_extn_cps',
      sub1: 'oceanhero',
      v: '1.4',
      ...(ip && { ip }),
    });

    const url = `https://${qs.get('partner')}.cps.ampfeed.com/suggestions?${qs}`;
    if (!inMemory[url]) {
      const response = await fetch(url, { signal: timeoutSignal(1000) });
      inMemory[url] = response.status === 200 ? (await response.json()) : null;
    }

    return inMemory[url];
  } catch (err) {
    console.error('requestAdSuggestions', err);
    return adSuggestionsDefault;
  }
};

export const requestPopularWebsites = (): Promise<PopularWebsite[]> =>
  import('../data/popularWebsites.json').then((result) => ([
    ...appsList.map(({ name, url }) => ({ url, term: name })),
    ...result.default.map(({ term, url }) => ({ url: withHttp(url), term })),
  ]));

export const requestHistory = async (): Promise<HistoryPage[]> => {
  const { browserHistory } = await getStorageItems(['browserHistory']);
  return browserHistory;
}

export const removeHistorySuggestion = async (url: string): Promise<HistoryPage[]> => {
  const current = await requestHistory();
  const browserHistory = current.filter((history) => history.url !== url);
  await setStorageItems({ browserHistory });
  return browserHistory;
}

export const requestZeropark = async (): Promise<Zeropark> => {
  const { zp } = await getStorageItems<{zp: Zeropark}>(['zp']);
  if (!zp?.brands?.length) return null;

  return {
    ...zp,
    brands: zp.brands
      .map((brand) => ({
        ...brand,
        // @ts-ignore
        keywords: brand.keywords.split(','),
      }))
      .sort((a) => -a.eCpc),
  }
}

