// ACTIONS

export const {
  toggleBookmarksNotification,
  setBookmarksTooltip,
  shownOnboardingStep,
  hideOnboardingStep,
  trackedRetention,
  updatedUser,
  createdUser,
  gainedShells,
  fetchedUserId,
  setInstallSource,
} = userSlice.actions;

export default userSlice.reducer;
