import { sendMessage } from '../chromeApi';
import storage from '../storage';

interface OutboundEvent {
  variant: string;
  payload: unknown;
}

export const trackOutbound = (events: OutboundEvent[]): void => {
  if (process.env.APP_PLATFORM === 'web') {
    const delayedEvents = storage.getJSON('delayedEvents') || [];
    storage.saveJSON('delayedEvents', [...delayedEvents, ...events]);
    return;
  }

  sendMessage({ type: 'trackAnalytics', events }).catch(console.error);
};
