import { createAsyncThunk } from '@reduxjs/toolkit';
import { getTopSites } from '../../../../shared/chromeApi';
import { GlobalState } from '../../../types.global';
import { AdMarketplaceTile } from './types';
import { selectFeatureFlags } from '../../../store/selectors';
import { fetchAffinity } from '../../../../shared/affinity';
import { selectIsUserRegular } from "../../../store/selectors";

const AD_MARKETPLACE = {
  partner: 'oceanhero_extn_tiles',
  sub1: '10112',
};

const getVevoTiles = (userId: string): Promise<AdMarketplaceTile[]> => fetchAffinity(userId, {
  n: '20',
  i: '1',
  is: '96x96',
  ist: '3',
  itype: 'cs',
})
  .then((list) => (list || []).map((tile): AdMarketplaceTile => ({
    id: Number(tile.rank),
    name: tile.brand,
    click_url: tile.rurl,
    image_url: tile.iurl,
    impression_url: tile.impurl,
    provider: 'affinity',
  })))
  .catch((err) => {
    console.error('bannerPromise', err);
    return [];
  });

const getAdMarketplaceTiles = (): Promise<AdMarketplaceTile[]> => {
  // ip: '72.229.28.185'
  const ip = localStorage.getItem('ip');
  return fetch(
    `https://${
      AD_MARKETPLACE.partner
    }.tiles.ampfeed.com/tiles?${new URLSearchParams({
      ...AD_MARKETPLACE,
      sub2: 'oceanhero',
      v: '1.3',
      rfr: 'https://chrome.google.com/webstore/detail/oceanhero-search-the-web/ijpgjiobapjdadigoagamcmhmdfdggmg',
      // results: '4',
      results: '100',
      ...(ip && { ip }),
    })}`
  )
    .then((res) => res.json())
    .then((tileResult) => (tileResult || {}).tiles || [])
    .then((list) => list.map((tile: AdMarketplaceTile): AdMarketplaceTile => ({ ...tile, provider: 'adMarketplace' })))
    .catch((err) => {
      console.error('tilesPromise', err);
      return { tiles: [] };
    });
};

type TopSitesResult = { value: chrome.topSites.MostVisitedURL[]; savedAt: number };
type AdTilesResult = { value: AdMarketplaceTile[]; savedAt: number };

export const fetchTiles = createAsyncThunk(
  'tiles/fetchTiles',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as GlobalState;
    const [topSites, adTiles] = await Promise.all([
      (async (): Promise<TopSitesResult> => {
        const value = await getTopSites();
        return { value, savedAt: Date.now() };
      })(),
      (async (): Promise<AdTilesResult> => {
        const { AD_TILES, FIFTH_TILE } = selectFeatureFlags(state);
        // const { savedAt } = state.tiles.adTiles;
        if (AD_TILES && selectIsUserRegular(state)) {
          // const newAdTiles = await (AD_TILES === 'siteplug'
          //   ? getSitePlugTiles
          //   : getAdMarketplaceTiles)(userId);

          const result = await Promise.all([
            getAdMarketplaceTiles(),
            FIFTH_TILE ? getVevoTiles(state.user.userId) : Promise.resolve([]),
          ]);

          return { value: result.flat(), savedAt: Date.now() };

          // if (!savedAt || savedAt < Date.now() - timeInMs.minute) {
          // }
        }
      })(),
    ]);

    return { topSites, adTiles };
  }
);
