import store from '../../newtab/store';
import { getAmplitudeUserProperties } from './utils';

let AMPLITUDE_KEY;

let amplitude;
let amplitudePromise;

export const getAmplitude = <T>(cb: (amplitude) => void): T => {
  console.log('getAmplitude', AMPLITUDE_KEY);
  return AMPLITUDE_KEY ? amplitudePromise.then(cb) : Promise.resolve(null);
};

export const trackAmplitudeEvent = (
  eventName: string,
  eventProperties?: Record<string, string | number>,
  state = store.getState()
): void => {
  console.log('trackAmplitudeEvent', eventName, eventProperties);
  getAmplitude(async (amplitude) => {
    console.log('trackAmplitudeEvent', eventName, eventProperties);
    const instance = amplitude.getInstance();
    const userProperties = await getAmplitudeUserProperties(state);
    instance.setUserProperties(userProperties);
    instance.logEvent(eventName, eventProperties);
  });
};

export const trackAmplitudeRevenue = (
  {
    productId,
    price,
    quantity,
    category,
  }: { productId: string; price: number; quantity: number; category: string },
  state = store.getState()
): void => {
  getAmplitude(async (amplitude) => {
    const instance = amplitude.getInstance();
    const userProperties = await getAmplitudeUserProperties(state);
    instance.setUserProperties(userProperties);

    const revenue = new instance.Revenue()
      .setProductId(productId)
      .setPrice(price)
      .setQuantity(quantity || 1)
      .setEventProperties({ category });
    instance.logRevenueV2(revenue);
  });
};

export const initAmplitude = (amplitudeKey: string): void => {
  AMPLITUDE_KEY = amplitudeKey;

  if (amplitudeKey) {
    amplitudePromise = import('amplitude-js').then((result) => {
      amplitude = result.default;

      const instanceInstance = amplitude.getInstance();
      instanceInstance.init(amplitudeKey);

      return amplitude;
    });

    amplitudePromise.catch((err) => {
      console.error('Imported amplitude error', err);
    });
  }
};

export const initAnalytics = (amplitudeKey: string): void => {
  initAmplitude(amplitudeKey);
};
